<?php
require_once '../includes/auth.php';require_once '../includes/functions.php';if(isTenantUser())requireTenant();global $conn;
$cols=[];$q=$conn->query("SHOW COLUMNS FROM pppoe_servers");while($x=$q->fetch_assoc())$cols[]=$x['Field'];$has=fn($c)=>in_array($c,$cols,true);$tid=getCurrentTenantId();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf();$name=trim($_POST['name']??'');if(($has('name')||$has('server_name'))&&!$name)$errors[]='Server name is required.';if(!$errors){$map=['name'=>$name,'server_name'=>$name,'router_id'=>(int)($_POST['router_id']??0),'interface'=>trim($_POST['interface']??''),'service_name'=>trim($_POST['service_name']??''),'status'=>$_POST['status']??'active'];$f=[];$v=[];$t='';foreach($map as $c=>$x)if($has($c)){$f[]=$c;$v[]=$x;$t.=is_int($x)?'i':'s';}if($has('tenant_id')){$f[]='tenant_id';$v[]=$tid;$t.='i';}$st=$conn->prepare("INSERT INTO pppoe_servers (".implode(',',$f).") VALUES (".implode(',',array_fill(0,count($f),'?')).")");if($st){$st->bind_param($t,...$v);if($st->execute())redirect('index.php');$errors[]=$st->error;}}}
