<?php require '../includes/header.php';?><div class="page-content"><div class="page-header"><div><h1>Add PPPoE Server</h1></div><a class="btn btn-secondary" href="index.php">Back</a></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="card" style="max-width:760px;padding:22px"><form method="post"><?=csrfField()?><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><?php if($has('name')||$has('server_name')):?><label>Name<input name="name" required></label><?php endif;?><?php if($has('router_id')):?><label>Router ID<input type="number" name="router_id"></label><?php endif;?><?php if($has('interface')):?><label>Interface<input name="interface" placeholder="ether1"></label><?php endif;?><?php if($has('service_name')):?><label>Service Name<input name="service_name"></label><?php endif;?><?php if($has('status')):?><label>Status<select name="status"><option>active</option><option>inactive</option></select></label><?php endif;?></div><button class="btn btn-primary" style="margin-top:18px">Save Server</button></form></div></div><?php require '../includes/footer.php';?>